import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# HIP source for fused Batch Norm (inference) and Scaling
fused_bn_scale_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_bn_scale_kernel(
    const float* __restrict__ input,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float scaling_factor,
    float eps,
    int batch_size,
    int channels,
    int height,
    int width) {

    int nc = blockIdx.x * blockDim.x + threadIdx.x;
    int total_channels = batch_size * channels;

    if (nc < total_channels) {
        int c = nc % channels;
        float mean = running_mean[c];
        float var = running_var[c];
        float w = weight[c];
        float b = bias[c];

        float inv_std = 1.0f / sqrtf(var + eps);
        float factor = w * inv_std * scaling_factor;
        float offset = (b - mean * w * inv_std) * scaling_factor;

        int channel_offset = nc * height * width;
        for (int hw = 0; hw < height * width; ++hw) {
            output[channel_offset + hw] = input[channel_offset + hw] * factor + offset;
        }
    }
}

torch::Tensor fused_bn_scale_hip(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float scaling_factor,
    float eps) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    int total_channels = batch_size * channels;
    int threads_per_block = 256;
    int blocks = (total_channels + threads_per_block - 1) / threads_per_block;

    hipLaunchKernelGGL(fused_bn_scale_kernel, blocks, threads_per_block, 0, 0,
        input.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        eps,
        batch_size,
        channels,
        height,
        width
    );

    return output;
}
"""

fused_bn_scale_lib = load_inline(
    name="fused_bn_scale",
    cpp_sources=fused_bn_scale_source,
    functions=["fused_bn_scale_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = float(scaling_factor)

    def forward(self, x):
        x = self.conv(x)
        # Assuming inference mode for optimization. If training, we would need a different approach.
        # However, for the context of this benchmark, let's see if this is sufficient.
        if self.bn.training:
            # Fallback to standard PyTorch during training to ensure correctness
            x = self.bn(x)
            x = x * self.scaling_factor
            return x
        else:
            return fused_bn_scale_lib.fused_bn_scale_hip(
                x,
                self.bn.running_mean,
                self.bn.running_var,
                self.bn.weight,
                self.bn.bias,
                self.scaling_factor,
                self.bn.eps
            )

